parameters.example:
terraform {
  required_providers {
    alicloud = {
      source   = "aliyun/alicloud"
      version  = "1.254.0"
    }
  }
}

resource "alicloud_vpc" "default" {
  is_default                                  = false
  enable_ipv6                                 = false
  classic_link_enabled                        = false
  force_delete                                = false
  system_route_table_route_propagation_enable = false
  dry_run                                     = false
}
